const A=document.getElementById('app');
const S={token:null,role:null,email:'',user:null,view:'inicio',admin:null,selectedPlan:localStorage.getItem('thiago_selected_plan')||null,attachments:[],mode:'chat',restoreColorize:false,workMode:false,language:localStorage.getItem('thiago_language')||'Español'};
function loadRoleToken(){const a=sessionStorage.getItem('thiago_admin_token'),c=sessionStorage.getItem('thiago_client_token');if(a){S.token=a;S.role='admin'}else if(c){S.token=c;S.role='client'}else{S.token=null;S.role=null}}
loadRoleToken();
function friendlyError(message='',code=''){const raw=String(message||'');if(/429|openai|api|billing|credit|quota|insufficient|saldo|provider/i.test(raw+' '+code))return 'El servicio de IA está temporalmente sin disponibilidad. Inténtalo nuevamente más tarde.';return raw||'No se pudo completar la solicitud.'}async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json',...(S.token?{Authorization:'Bearer '+S.token}:{})};const r=await fetch(url,opt);const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(friendlyError(d.error,d.code));return d}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
const planName=p=>({basic:'BÁSICO',pro:'PRO',business:'NEGOCIO'}[p]||'SIN PLAN');
function login(){A.innerHTML=`<section class="login"><div class="card login-card"><div class="logo">THIAGO <span>IA</span></div><p class="sub">La inteligencia artificial en tus manos</p><input id="email" class="field" type="email" placeholder="Correo electrónico" onkeydown="if(event.key==='Enter'){event.preventDefault();requestAccess()}"><button class="primary" onclick="requestAccess()">CONTINUAR →</button><button class="prices-toggle" onclick="togglePublicPlans()">◇ VER PLANES Y PRECIOS</button><div id="publicPlans" class="public-plans hidden">${publicPlansHtml()}</div><button class="link" onclick="adminLogin()">Acceso de administrador</button><p class="muted">¿Primera vez? Tu cuenta se crea automáticamente.</p></div></section>`}
function publicPlansHtml(){const ps=[
['basic','BÁSICO',85,'✦','Para comenzar',['Chat con IA e investigación','Crear y mejorar imágenes','Restaurar fotografías','Traducción de textos','Documentos Word en Arial 12'],['Vectorización profesional']],
['pro','PRO',180,'★','MÁS POPULAR',['Todo lo del plan BÁSICO','Mayor capacidad de imágenes','Mejorar y restaurar imágenes','Vectorización profesional incluida (uso limitado)','Documentos y herramientas avanzadas'],[]],
['business','NEGOCIO',300,'♛','MÁXIMO PODER',['Todo lo del plan PRO','Mayor capacidad diaria de imágenes','Vectorización con uso amplio incluido','Herramientas para trabajo intensivo','Prioridad para funciones avanzadas'],[]]
];return `<div class="public-plan-head"><span class="public-plan-kicker">★ ELIGE TU PLAN</span><h2>Elige el <em>plan ideal</em> para ti</h2><p>Funciones claras para cada nivel de trabajo. La activación y los cambios siempre requieren aprobación del administrador.</p></div><div class="public-service-strip"><span>◉ <b>Chat con IA</b><small>e investigación</small></span><span>▧ <b>Crear y mejorar</b><small>imágenes</small></span><span>✣ <b>Restaurar</b><small>fotografías</small></span><span>文 <b>Traducción</b><small>de textos</small></span><span>◇ <b>Vectorización</b><small>profesional</small></span><span>▤ <b>Documentos Word</b><small>Arial 12</small></span></div><div class="public-plan-grid">${ps.map(p=>`<div class="public-plan premium-public ${p[0]==='pro'?'featured':''} ${p[0]==='business'?'business':''} ${S.selectedPlan===p[0]?'selected':''}"><div class="pp-top"><span class="pp-icon">${p[3]}</span><span class="pp-tag">${p[4]}</span></div><h3>${p[1]}</h3><div class="pp-price">Q${p[2]}<small>/ 30 días</small></div><div class="pp-features">${p[5].map(x=>`<span class="yes">✓ ${x}</span>`).join('')}${p[6].map(x=>`<span class="no">× ${x}</span>`).join('')}</div><button class="choose-plan" onclick="selectPublicPlan('${p[0]}')">${S.selectedPlan===p[0]?'✓ SELECCIONADO':'ELEGIR '+p[1]}</button></div>`).join('')}</div><div class="selected-plan-box ${S.selectedPlan?'':'hidden'}">${selectedPlanText()}</div><p class="plan-note">Selecciona el plan que mejor se adapte a tus necesidades. Después ingresa tu correo y código; la activación queda pendiente de aprobación del administrador.</p>`}
function togglePublicPlans(){document.getElementById('publicPlans')?.classList.toggle('hidden')}
function selectedPlanText(){const x={basic:'BÁSICO — Q85',pro:'PRO — Q180',business:'NEGOCIO — Q300'};return S.selectedPlan?`Has seleccionado <b>${x[S.selectedPlan]}</b>. Ahora escribe tu correo y presiona CONTINUAR.`:''}
function selectPublicPlan(plan){S.selectedPlan=plan;localStorage.setItem('thiago_selected_plan',plan);const box=document.getElementById('publicPlans');if(box){box.innerHTML=publicPlansHtml();box.classList.remove('hidden')}}
async function requestAccess(){const email=document.getElementById('email').value.trim();if(!email)return alert('Escriba su correo');S.email=email;try{let d=await api('/api/access/request',{method:'POST',body:JSON.stringify({email})});if(d.needsRegistration)return register();codeScreen()}catch(e){alert(e.message)}}
function register(){A.innerHTML=`<section class="login"><div class="card"><h2>¡Bienvenido! 👋</h2><p class="sub">Completa tus datos.</p><input id="name" class="field" placeholder="Nombre completo"><input class="field" value="${esc(S.email)}" disabled><input id="phone" class="field" placeholder="WhatsApp (opcional)"><button class="primary" onclick="finishRegister()">CREAR CUENTA</button><button class="link" onclick="login()">Volver</button></div></section>`}
async function finishRegister(){try{await api('/api/access/request',{method:'POST',body:JSON.stringify({email:S.email,name:document.getElementById('name').value,phone:document.getElementById('phone').value})});codeScreen()}catch(e){alert(e.message)}}
function codeScreen(){A.innerHTML=`<section class="login"><div class="card"><h2>🔐 Código de acceso</h2><p class="sub">Código de 6 dígitos para <b>${esc(S.email)}</b>.<br>Vence en 10 minutos y es de un solo uso.</p><input id="code" class="field code" maxlength="6" inputmode="numeric" placeholder="••••••" onkeydown="if(event.key==='Enter'){event.preventDefault();verifyCode()}"><button class="primary" onclick="verifyCode()">ENTRAR</button><button class="link" onclick="requestAccess()">Generar otro código</button></div></section>`}
async function verifyCode(){try{const d=await api('/api/access/verify',{method:'POST',body:JSON.stringify({email:S.email,code:document.getElementById('code').value})});S.token=d.token;S.role='client';S.user=d.user;sessionStorage.setItem('thiago_client_token',S.token);if(S.selectedPlan&&S.user.plan!==S.selectedPlan){await api('/api/plans/request',{method:'POST',body:JSON.stringify({plan:S.selectedPlan})});localStorage.removeItem('thiago_selected_plan');S.selectedPlan=null;alert('Solicitud de plan enviada al administrador.')}S.view='inicio';client()}catch(e){alert(e.message)}}
function adminLogin(){A.innerHTML=`<section class="login"><div class="card"><h2>Administrador</h2><input id="akey" class="field" type="password" placeholder="Clave de administrador" onkeydown="if(event.key==='Enter'){event.preventDefault();doAdminLogin()}"><button class="primary" onclick="doAdminLogin()">ENTRAR AL ADMIN</button><button class="link" onclick="login()">Volver</button></div></section>`}
async function doAdminLogin(){try{const d=await api('/api/admin/login',{method:'POST',body:JSON.stringify({key:document.getElementById('akey').value})});S.token=d.token;S.role='admin';sessionStorage.setItem('thiago_admin_token',S.token);S.view='dashboard';admin()}catch(e){alert(e.message)}}
async function logout(){try{await api('/api/logout',{method:'POST'})}catch{}if(S.role==='admin')sessionStorage.removeItem('thiago_admin_token');else sessionStorage.removeItem('thiago_client_token');S.token=null;S.role=null;S.user=null;login()}
const nav=role=>`<aside class="side"><div class="brand">THIAGO <b>IA</b></div><div class="nav">${role==='client'?`<button onclick="newChat()">＋ Nuevo chat</button><button onclick="S.view='herramientas';client()">✦ Herramientas</button><button onclick="S.view='historial';client()">◷ Historial</button><button onclick="S.view='planes';client()">◇ Planes</button><button onclick="S.view='cuenta';client()">♙ Mi cuenta</button><button onclick="S.view='pagocliente';client()">▣ Pagos</button><button onclick="S.view='idioma';client()">🌐 Idioma</button><button onclick="openVectorTool()">◇ Vectorizar <span class="vector-badge">PRO / NEGOCIO</span></button>`:`<button onclick="S.view='dashboard';admin()">▦ Dashboard</button><button onclick="S.view='accesos';admin()">🔑 Solicitudes de acceso</button><button onclick="S.view='planes';admin()">◇ Solicitudes de plan</button><button onclick="S.view='usuarios';admin()">♙ Usuarios</button><button onclick="S.view='pagos';admin()">$ Pagos</button><button onclick="S.view='renovaciones';admin()">↻ Renovaciones</button><button onclick="S.view='config';admin()">⚙ Configuración</button>`}<button onclick="logout()">↪ Cerrar sesión</button></div>${role==='client'&&S.user?.plan?sideStats():''}</aside>`;
function sideStats(){const st=planState();return `<div class="side-stats"><div class="side-stat card"><span class="muted">PLAN ACTIVO</span><div class="stat">${planName(S.user.plan)}</div><button class="link" onclick="S.view='planes';client()">Cambiar / renovar →</button></div><div class="side-stat card usage-card"><span class="muted">IMÁGENES HOY</span><div class="stat" id="usagePct">${S.user.imageUsage?.percent??100}%</div><div class="usage-track"><div class="usage-fill" style="width:${S.user.imageUsage?.percent??100}%"></div></div><small class="muted">Reinicia 6:00 a. m.</small></div><div class="side-stat card"><span class="muted">VENCIMIENTO</span><div class="stat smallstat">${new Date(S.user.planExpires).toLocaleDateString()}</div><span>${st.days} días restantes</span></div></div>`}
async function client(){try{S.user=(await api('/api/me')).user}catch{return login()}let body='';if(S.view==='planes')body=plansView();else if(S.view==='cuenta')body=accountView();else if(S.view==='idioma')body=languageView();
  else if(S.view==='pagocliente')body=paymentClientView();else if(S.view==='historial')body=historyView();else if(S.view==='herramientas')body=toolsView();else body=homeClient();A.innerHTML=`<div class="shell">${nav('client')}<main class="main ${S.workMode&&S.view==='inicio'?'work-mode':''}"><div class="topbar"><span class="badge">CLIENTE</span><span>${esc(S.user.name||S.user.email)}</span></div>${body}</main></div>`}
function languageView(){const langs=['Español','English','Português','Français','Deutsch','Italiano'];return `<div class="card language-card"><h2>🌐 Idioma</h2><p class="muted">Selecciona el idioma principal de THIAGO IA. Quedará guardado para tus próximas sesiones.</p><select id="languageSelect" class="field language-select" onchange="saveLanguage(this.value)">${langs.map(l=>`<option value="${l}" ${S.language===l?'selected':''}>${l}</option>`).join('')}</select><p class="language-current">Idioma actual: <b>${esc(S.language)}</b></p></div>`}
function saveLanguage(lang){S.language=lang||'Español';localStorage.setItem('thiago_language',S.language);client()}
function accountView(){const st=planState(),u=S.user||{};const phone=u.phone||'No registrado';const member=u.createdAt?new Date(u.createdAt).toLocaleDateString():'—';const activated=u.planStartedAt?new Date(u.planStartedAt).toLocaleDateString():'—';return `<section class="account-page"><div class="section-title"><span class="eyebrow">THIAGO IA · PERFIL DEL CLIENTE</span><h1>Mi cuenta</h1><p>Tu información de acceso, plan y uso en un solo lugar.</p></div><div class="account-hero card"><div class="account-avatar">${esc((u.name||u.email||'T').trim().charAt(0).toUpperCase())}</div><div class="account-identity"><span class="badge">CLIENTE</span><h2>${esc(u.name||'Cliente')}</h2><p>${esc(u.email||'')}</p><p class="muted">${esc(phone)}</p></div><button class="primary inline-primary" onclick="S.view='planes';client()">Cambiar / renovar plan</button></div><div class="account-grid"><div class="card account-detail"><span>Plan activo</span><strong>${planName(u.plan)}</strong><small>${st.active?st.days+' días restantes':'Sin plan activo'}</small></div><div class="card account-detail"><span>Imágenes hoy</span><strong>${u.imageUsage?.percent??100}%</strong><small>Reinicia 6:00 a. m.</small></div><div class="card account-detail"><span>Vencimiento</span><strong>${u.planExpires?new Date(u.planExpires).toLocaleDateString():'—'}</strong><small>${st.active?st.days+' días restantes':'—'}</small></div><div class="card account-detail"><span>Idioma</span><strong>${esc(S.language)}</strong><small>Preferencia guardada</small></div><div class="card account-detail"><span>Activación del plan</span><strong>${activated}</strong><small>Última activación aprobada</small></div><div class="card account-detail"><span>Miembro desde</span><strong>${member}</strong><small>Cuenta THIAGO IA</small></div></div><div class="account-actions"><button class="smallbtn" onclick="S.view='historial';client()">Ver historial</button><button class="smallbtn" onclick="S.view='idioma';client()">Cambiar idioma</button></div></section>`}
function planState(){if(!S.user.plan||!S.user.planExpires)return {active:false,expired:false,days:null};const ms=new Date(S.user.planExpires).getTime()-Date.now();return {active:ms>0,expired:ms<=0,days:Math.max(0,Math.ceil(ms/86400000))}}
function expiryNotice(){const st=planState();if(!st.active)return '';if(st.days<=1)return `<div class="expiry-alert danger"><b>⚠ Tu plan vence mañana.</b> Puedes solicitar tu renovación desde Planes.</div>`;if(st.days<=5)return `<div class="expiry-alert"><b>⏳ Tu plan vence en ${st.days} días.</b> Puedes renovarlo con anticipación.</div>`;return ''}
function homeClient(){const st=planState();if(!S.user.plan)return `<div class="hero"><h1>¡Hola, ${esc((S.user.name||'Cliente').split(' ')[0])}! 👋</h1><p class="sub">Elige un plan para comenzar con THIAGO IA.</p></div>${plansView()}`;if(st.expired)return `<div class="hero"><h1>Plan vencido</h1><p class="sub">Tu acceso a las herramientas de THIAGO IA está pausado.</p></div><div class="card expired-card"><h2>🔒 ${planName(S.user.plan)} vencido</h2><p>Venció el ${new Date(S.user.planExpires).toLocaleDateString()}.</p><p class="muted">Solicita una renovación. El administrador verificará el pago y, al aprobarla, tendrás otros 30 días.</p><button class="primary" onclick="S.view='planes';client()">RENOVAR PLAN</button></div>`;return `${expiryNotice()}<div class="hero client-hero"><h1>¡Hola, ${esc((S.user.name||'Cliente').split(' ')[0])}! 👋</h1><p class="sub">¿En qué puedo ayudarte hoy?</p></div>${workspace()}`}
function workspace(){const has=loadHistory().length>0;return `<div class="workspace transparent-workspace"><div class="feature-strip"><button onclick="setMode('editimage')"><b>▧ Mejorar imagen</b><small>Más nitidez y calidad</small></button><button onclick="setMode('restore')"><b>♻ Restaurar imagen</b><small>Recupera fotos antiguas</small></button><button onclick="setMode('translate')"><b>文 Traducción</b><small>Traduce textos</small></button><button onclick="setMode('vectorize')"><b>✂ Vectorizar imagen</b><small>SVG / PDF vectorial</small></button><button onclick="setMode('document')"><b>▤ Documento Word</b><small>Generar .docx Arial 12</small></button></div><div class="start-prompt ${has?'hidden':''}" onclick="document.getElementById('prompt')?.focus()"><span>✦</span><div><b>¿Qué deseas hacer ahora?</b><small>Puedes escribir, arrastrar una imagen o pegar con Ctrl + V</small></div><i>➜</i></div><div id="messages" class="messages ${has?'':'empty-messages'}">${loadHistory().map(renderMsg).join('')}</div><div class="composer-dock"><div id="attachList" class="attach-list"></div><div class="composer big" ondragenter="dragComposer(event)" ondragover="dragComposer(event)" ondragleave="leaveComposer(event)" ondrop="dropComposer(event)"><label class="attach" title="Adjuntar archivo">＋<input id="fileInput" type="file" multiple accept="image/*,.pdf,.txt,.md,.csv,.doc,.docx" onchange="pickFiles(event)"></label><textarea id="prompt" class="field" rows="2" placeholder="Escribe tu mensaje o arrastra una imagen aquí..." onkeydown="composerKey(event)" onfocus="activateWorkMode()" oninput="activateWorkMode()"></textarea><button class="send" onclick="sendCurrent()">➤</button></div><div class="dock-tools"><button onclick="setMode('research')">⌕ Investigar</button><button onclick="setMode('ocr')">▤ Extraer texto</button><button onclick="setMode('translate')">◎ Traducir</button><button onclick="S.view='herramientas';client()">⚒ Herramientas</button><span>Enter para enviar · Shift + Enter para nueva línea</span></div></div></div>`}
function renderMsg(x){if(x.image)return `<div class="msg ai"><div>${esc(x.text||'Imagen')}</div><img class="generated" src="${x.image}" alt="Imagen"><a class="download" href="${x.image}" download="thiago-ia.png">Abrir / guardar imagen</a></div>`;return `<div class="msg ${x.role==='user'?'me':'ai'}">${esc(x.text)}</div>`}
function activateWorkMode(){if(S.view!=='inicio')return;S.workMode=true;document.querySelector('main.main')?.classList.add('work-mode');document.querySelector('.start-prompt')?.classList.add('hidden');document.querySelector('.messages')?.classList.remove('empty-messages')}
function composerKey(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendCurrent()}}
function scrollWork(){const box=document.getElementById('messages');if(box){box.scrollTop=box.scrollHeight;box.lastElementChild?.scrollIntoView({behavior:'smooth',block:'nearest'})}}
function goHome(){S.mode='chat';S.view='inicio';client();setTimeout(()=>{document.getElementById('prompt')?.focus();installPasteHandler()},50)}
function newChat(){S.workMode=false;const old=loadHistory();if(old.length){const chats=JSON.parse(localStorage.getItem('thiago_chats')||'[]');chats.unshift({id:Date.now(),title:(old.find(x=>x.role==='user')?.text||'Conversación').slice(0,60),at:new Date().toISOString(),messages:old});safeStore('thiago_chats',chats.slice(0,30))}localStorage.removeItem('thiago_history');S.attachments=[];S.mode='chat';S.view='inicio';client()}
function markRestore(btn){document.querySelectorAll('.restore-options button').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected')}
function openVectorTool(){if(!['pro','business'].includes(S.user?.plan)){alert('Vectorización profesional está disponible en los planes PRO y NEGOCIO. Puedes actualizar tu plan desde Planes.');S.view='planes';return client()}S.mode='vectorize';S.view='inicio';S.workMode=true;client();setTimeout(()=>document.getElementById('prompt')?.focus(),80)}
function toolsView(){const t=[['💬','Chat IA','Preguntas, ideas y redacción','chat'],['🔎','Investigación','Investigar y resumir información','research'],['🖼️','Imágenes con THIAGO IA','Escribe lo que necesitas. Si adjuntas una imagen, THIAGO IA la editará; si no adjuntas, creará una nueva.','chat'],['📎','Archivos y documentos','Analizar PDF, imágenes y documentos','document'],['🔤','Extraer texto OCR','Leer texto visible en una imagen','ocr'],['🌐','Traducción','Traducir y corregir textos','translate'],['📄','Word / PDF / Excel / PowerPoint','Crear archivos reales y descargables','document'],['◇','Vectorización profesional','SVG vectorial real · exclusivo NEGOCIO','vectorize']];return `<div class="hero"><h1>Herramientas</h1><p class="sub">Selecciona lo que quieres hacer.</p></div><div class="tool-grid">${t.map(x=>`<button class="tool-card" onclick="openTool('${x[3]}')"><span>${x[0]}</span><b>${x[1]}</b><small>${x[2]}</small></button>`).join('')}</div>`}
function openTool(mode){if(mode==='vectorize')return openVectorTool();S.mode=mode;S.view='inicio';client();setTimeout(()=>{setMode(mode);document.getElementById('prompt')?.focus()},0)}
function setMode(mode){S.mode=mode;const titles={chat:'Asistente inteligente',research:'Investigación',image:'Generar imagen',editimage:'Modificar imagen',document:'Analizar documentos',ocr:'Extraer texto (OCR)',translate:'Traducción y corrección',restore:'Restaurar fotografía antigua'};const e=document.getElementById('modeTitle');if(e)e.textContent=titles[mode]||titles.chat;const p=document.getElementById('prompt');if(p){const ph={image:'Describe con detalle la imagen profesional que quieres generar...',editimage:'Adjunta una imagen y describe qué quieres modificar...',ocr:'Adjunta una imagen para extraer el texto...',research:'¿Qué deseas investigar?',translate:'Pega o escribe el texto y dime a qué idioma...',document:'Adjunta el documento y dime qué necesitas...',restore:'Adjunta la fotografía antigua. Puedes indicar detalles adicionales...'};p.placeholder=ph[mode]||'Escribe tu mensaje...';p.focus();installPasteHandler()}document.getElementById('restoreOptions')?.classList.toggle('hidden',mode!=='restore')}
async function pickFiles(ev){const files=[...ev.target.files];S.attachments=[];for(const f of files.slice(0,4)){if(f.size>7*1024*1024){alert(f.name+' supera 7 MB');continue}const data=await fileData(f);S.attachments.push({name:f.name,type:f.type||'application/octet-stream',data})}renderAttachments()}
async function addDroppedFiles(files){const incoming=[...files].slice(0,4);for(const f of incoming){if(f.size>7*1024*1024){alert(f.name+' supera 7 MB');continue}const allowed=String(f.type||'').startsWith('image/')||/\.(pdf|txt|md|csv|doc|docx)$/i.test(f.name||'');if(!allowed){alert('Archivo no compatible: '+(f.name||'archivo'));continue}const data=await fileData(f);S.attachments.push({name:f.name||'imagen-arrastrada',type:f.type||'application/octet-stream',data})}renderAttachments();document.getElementById('prompt')?.focus()}
function dragComposer(e){e.preventDefault();e.stopPropagation();e.currentTarget?.classList.add('drag-active');if(e.dataTransfer)e.dataTransfer.dropEffect='copy'}
function leaveComposer(e){e.preventDefault();e.stopPropagation();if(e.currentTarget&&!e.currentTarget.contains(e.relatedTarget))e.currentTarget.classList.remove('drag-active')}
async function dropComposer(e){e.preventDefault();e.stopPropagation();e.currentTarget?.classList.remove('drag-active');const files=[...(e.dataTransfer?.files||[])];if(!files.length)return;await addDroppedFiles(files)}
function fileData(f){return new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f)})}
function renderAttachments(){const e=document.getElementById('attachList');if(!e)return;e.innerHTML=S.attachments.map((f,i)=>String(f.type).startsWith('image/')?`<div class="attachment-preview"><img src="${f.data}" alt="${esc(f.name)}"><div><span>${esc(f.name)}</span><button onclick="S.attachments.splice(${i},1);renderAttachments()">×</button></div></div>`:`<span class="file-chip">📎 ${esc(f.name)} <button onclick="S.attachments.splice(${i},1);renderAttachments()">×</button></span>`).join('')}
function historySafe(items){return (items||[]).map(x=>({role:x.role,text:x.text||'',at:x.at||Date.now()})).slice(-80)}
function safeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch(e){try{if(key==='thiago_history')localStorage.setItem(key,JSON.stringify(historySafe(value).slice(-40)));else if(key==='thiago_chats'){const slim=(value||[]).slice(0,20).map(c=>({...c,messages:historySafe(c.messages).slice(-40)}));localStorage.setItem(key,JSON.stringify(slim));}return true}catch{return false}}}
function saveHistory(role,text,image=null){let h=loadHistory();h.push({role,text,at:Date.now()});safeStore('thiago_history',historySafe(h))}
function loadHistory(){try{return historySafe(JSON.parse(localStorage.getItem('thiago_history')||'[]'))}catch{return []}}
function historyView(){const current=loadHistory(),chats=JSON.parse(localStorage.getItem('thiago_chats')||'[]');const saved=chats.map(c=>`<div class="chat-history-card"><div class="history-info" onclick="openSavedChat('${c.id}')"><b>${esc(c.title||'Conversación')}</b><small>${new Date(c.at).toLocaleString()}</small><span>Abrir y continuar →</span></div><button class="history-delete" onclick="event.stopPropagation();deleteSavedChat('${c.id}')">🗑 Eliminar</button></div>`).join('');return `<section class="history-page card"><div class="workspace-head"><div><span class="eyebrow">THIAGO IA</span><h2>Historial</h2><p class="muted">Abre un trabajo anterior, continúa donde quedaste o elimina lo que ya no necesites.</p></div><div class="head-actions"><button class="smallbtn dangerbtn" onclick="clearAllHistory()">🗑 Eliminar todo el historial</button><button class="smallbtn" onclick="newChat()">＋ Nuevo chat</button></div></div>${current.length?`<div class="chat-history-card current-chat"><div class="history-info" onclick="openCurrentChat()"><b>Conversación actual</b><span>${esc((current.find(x=>x.role==='user')?.text||'Trabajo actual').slice(0,90))}</span><small>Abrir y continuar →</small></div><button class="history-delete" onclick="event.stopPropagation();deleteCurrentChat()">🗑 Eliminar</button></div>`:''}${saved||(!current.length?'<div class="empty-history"><b>Aún no tienes trabajos guardados.</b><span>Cuando inicies conversaciones aparecerán aquí.</span></div>':'')}</section>`}
function clearAllHistory(){if(!confirm('¿Seguro que deseas eliminar TODO el historial? Esta acción no se puede deshacer.'))return;localStorage.removeItem('thiago_history');localStorage.removeItem('thiago_chats');S.attachments=[];client()}
function deleteCurrentChat(){if(!confirm('¿Eliminar la conversación actual?'))return;localStorage.removeItem('thiago_history');S.attachments=[];client()}
function deleteSavedChat(id){if(!confirm('¿Eliminar esta conversación del historial?'))return;const chats=JSON.parse(localStorage.getItem('thiago_chats')||'[]').filter(c=>String(c.id)!==String(id));safeStore('thiago_chats',chats);client()}
function openCurrentChat(){S.view='inicio';S.mode='chat';S.workMode=true;client()}
function openSavedChat(id){const chats=JSON.parse(localStorage.getItem('thiago_chats')||'[]'),c=chats.find(x=>String(x.id)===String(id));if(!c)return;safeStore('thiago_history',historySafe(c.messages||[]));S.view='inicio';S.mode='chat';S.workMode=true;client()}
function lastAssistantText(){const h=loadHistory();for(let i=h.length-1;i>=0;i--){if(h[i].role==='assistant'&&h[i].text&&!h[i].image)return h[i].text}return ''}
function requestedFormat(text){const t=(text||'').toLowerCase();if(/\b(word|docx)\b/.test(t))return 'docx';if(/\b(excel|xlsx)\b/.test(t))return 'xlsx';if(/\b(pdf)\b/.test(t))return 'pdf';if(/\b(powerpoint|pptx|presentaci[oó]n)\b/.test(t))return 'pptx';return null}
function isMostlyExportRequest(text){return /^(ahora\s+)?(p[aá]same|pasame|pon|haz|h[aá]zme|quiero|convi[eé]rtelo|convertir|exporta|descarga).{0,45}(word|docx|excel|xlsx|pdf|powerpoint|pptx|presentaci[oó]n)/i.test((text||'').trim())}
async function exportContent(format,content,title='Documento THIAGO IA'){if(!content)return alert('Primero genera o investiga contenido para crear el archivo.');const box=document.getElementById('messages');const wait=document.createElement('div');wait.className='msg ai working';wait.innerHTML='<span class="dots">● ● ●</span> THIAGO IA está creando el archivo descargable…';box.appendChild(wait);scrollWork();try{const d=await api('/api/export',{method:'POST',body:JSON.stringify({format,content,title})});wait.classList.remove('working');wait.innerHTML=`<div class="file-result"><b>Archivo listo.</b><br><a class="download" href="${d.url}" download>⬇ Descargar ${d.label}</a></div>`;saveHistory('assistant','Archivo '+d.label+' listo para descargar.');scrollWork()}catch(e){wait.classList.remove('working');wait.textContent=e.message;wait.classList.add('warn')}}
function installPasteHandler(){const p=document.getElementById('prompt');if(!p||p.dataset.pasteReady)return;p.dataset.pasteReady='1';p.addEventListener('paste',async e=>{const items=[...(e.clipboardData?.items||[])];const imageItem=items.find(i=>i.type&&i.type.startsWith('image/'));if(!imageItem)return;const file=imageItem.getAsFile();if(!file)return;e.preventDefault();try{const data=await fileToData(file);S.attachments.push({name:file.name||'imagen-pegada.png',type:file.type||'image/png',data});renderAttachments();p.focus()}catch(err){alert('No se pudo pegar la imagen: '+err.message)}})}

function requestedImageSize(text){
 const t=String(text||'').toLowerCase().replace(/×/g,'x');
 let m=t.match(/(\d+(?:[.,]\d+)?)\s*x\s*(\d+(?:[.,]\d+)?)\s*(cm|cent[ií]metros?|mm|px|p[ií]xeles?)?/i);
 if(!m)return null;
 const w=parseFloat(m[1].replace(',','.')),h=parseFloat(m[2].replace(',','.')); const unit=(m[3]||'').toLowerCase();
 if(!w||!h)return null;
 return {width:w,height:h,unit:unit.startsWith('mm')?'mm':unit.startsWith('px')||unit.startsWith('pí')||unit.startsWith('pi')?'px':'cm',orientation:h>w?'vertical':w>h?'horizontal':'square',aspectRatio:w/h};
}
function imageSizeInstruction(text){const z=requestedImageSize(text);if(!z)return '';return ` MEDIDA SOLICITADA OBLIGATORIA: ${z.width} x ${z.height} ${z.unit}. Conserva exactamente la relación de aspecto ${z.width}:${z.height} (${z.orientation}). No recortes contenido para forzar el formato. Si la API no puede producir físicamente esa medida, genera en la relación de aspecto más cercana y conserva todo el contenido; el archivo final debe prepararse con esa medida solicitada.`}
async function sendCurrent(){activateWorkMode();const p=document.getElementById('prompt'),text=p?.value.trim()||'';const attachedImage=S.attachments.find(a=>String(a.type).startsWith('image/'));if(attachedImage&&!text)return alert('Escribe qué deseas hacer con la imagen antes de enviarla.');if(S.mode==='vectorize'&&attachedImage&&text)return vectorizeImage(text,attachedImage);if(attachedImage&&text&&S.mode!=='ocr')return imageTransform(text,attachedImage,'edit',false);if(S.mode==='image')return generateImage(text);if(S.mode==='restore')return restoreImage(text);if(S.mode==='editimage')return editImage(text);if(S.attachments.length&&!text)return alert('Escribe qué deseas hacer con la imagen o archivo antes de enviarlo.');if(!text)return;if(!S.attachments.length&&/^(crea|crear|genera|generar|diseña|diseñar|hazme|realiza|realizar).{0,35}(imagen|diseño|logo|afiche|flyer|foto|ilustraci[oó]n)/i.test(text))return generateImage(text);const fmt=requestedFormat(text);if(fmt&&isMostlyExportRequest(text)&&lastAssistantText()){p.value='';return exportContent(fmt,lastAssistantText(),'Trabajo THIAGO IA')}let instruction=`Responde siempre en ${S.language||'Español'}, salvo que el usuario solicite explícitamente otro idioma en ese mensaje. Mantén ese idioma como idioma principal de la conversación. Solicitud: ${text}`;if(S.mode==='research')instruction=`Responde siempre en ${S.language||'Español'}, salvo petición explícita de otro idioma. Investiga y responde en formato limpio. No uses asteriscos, viñetas con símbolos, markdown decorativo ni encabezados con #. Si hay varios puntos, numéralos únicamente como 1., 2., 3., etc. Usa redacción normal con comas, punto seguido y punto final. Solicitud: ${text}`;if(S.mode==='ocr')instruction=`Responde en ${S.language||'Español'}. Extrae todo el texto visible de la imagen o documento adjunto. Respeta el texto extraído tal como aparece; las explicaciones deben estar en ${S.language||'Español'}. Solicitud: ${text||'Extraer texto'}`;if(S.mode==='translate')instruction=`Idioma principal de interfaz: ${S.language||'Español'}. En esta herramienta sí debes respetar el idioma destino que el usuario solicite. Solicitud: ${text}`;if(S.mode==='document')instruction=`Responde y prepara el documento en ${S.language||'Español'}, salvo que el usuario pida explícitamente otro idioma. Analiza o crea el contenido solicitado de forma profesional. Si el usuario pide Word, Excel, PDF o PowerPoint, prepara primero el contenido completo que debe incluir el archivo. Solicitud: ${text}`;const box=document.getElementById('messages');const sentAttachments=[...S.attachments];box.insertAdjacentHTML('beforeend',`<div class="msg me">${esc(text||'📎 Archivo adjunto')}</div>`);saveHistory('user',text||'[Archivo adjunto]');p.value='';S.attachments=[];renderAttachments();const wait=document.createElement('div');wait.className='msg ai working';wait.innerHTML='<span class="dots">● ● ●</span> THIAGO IA está trabajando…';box.appendChild(wait);scrollWork();try{const d=await api('/api/chat',{method:'POST',body:JSON.stringify({message:instruction,attachments:sentAttachments})});wait.classList.remove('working');wait.textContent=d.text;saveHistory('assistant',d.text);S.attachments=[];renderAttachments();scrollWork();if(fmt)await exportContent(fmt,d.text,'Trabajo THIAGO IA')}catch(e){wait.classList.remove('working');wait.textContent=e.message;wait.classList.add('warn');scrollWork()}}
async function generateImage(text){activateWorkMode();const p=document.getElementById('prompt');if(!text)return alert('Describe la imagen que quieres generar');const box=document.getElementById('messages');box.insertAdjacentHTML('beforeend',`<div class="msg me">${esc(text)}</div>`);saveHistory('user','[Imagen] '+text);if(p)p.value='';const wait=document.createElement('div');wait.className='msg ai working';wait.innerHTML='<span class="dots">● ● ●</span> THIAGO IA está creando una imagen profesional…';box.appendChild(wait);scrollWork();try{const d=await api('/api/image',{method:'POST',body:JSON.stringify({prompt:text+imageSizeInstruction(text),action:'generate',requestedSize:requestedImageSize(text)})});wait.classList.remove('working');wait.innerHTML=`<div>Imagen generada:</div><img class="generated" src="${d.image}" alt="Imagen generada"><a class="download" href="${d.image}" download="thiago-ia.png">Abrir / guardar imagen</a>`;saveHistory('assistant','Imagen generada: '+text,d.image);await refreshUser();scrollWork()}catch(e){wait.classList.remove('working');wait.textContent=e.message;wait.classList.add('warn');scrollWork()}}

async function vectorizeImage(text,img){
 if(!['pro','business'].includes(S.user?.plan))return alert('Vectorización profesional está disponible en los planes PRO y NEGOCIO.');
 const box=document.getElementById('messages'),p=document.getElementById('prompt');
 box.insertAdjacentHTML('beforeend',`<div class="msg me image-request"><img class="original-preview" src="${img.data}" alt="Original"><div class="request-text">${esc(text)}</div></div>`);
 if(p)p.value=''; const wait=document.createElement('div');wait.className='msg ai working';wait.textContent='THIAGO IA está vectorizando…';box.appendChild(wait);scrollWork();
 try{const d=await api('/api/vectorize',{method:'POST',body:JSON.stringify({prompt:text,image:img.data})});wait.className='msg ai';wait.innerHTML=`<div class="vector-result"><div><b>Vectorización completada</b><p>Archivo SVG vectorial listo.</p><a class="download" href="${d.svgDataUrl}" download="thiago-ia-vector.svg">Descargar SVG</a></div></div>`;S.attachments=[];renderAttachments();scrollWork()}catch(e){wait.className='msg ai warn';wait.textContent=e.message}
}

async function editImage(text){const img=S.attachments.find(a=>String(a.type).startsWith('image/'));if(!img)return alert('Adjunta primero la imagen que quieres modificar');if(!text)return alert('Describe qué quieres modificar');return imageTransform(text,img,'edit',false)}
async function restoreImage(text){const img=S.attachments.find(a=>String(a.type).startsWith('image/'));if(!img)return alert('Adjunta primero la fotografía antigua');if(!text)return alert('Escribe qué deseas hacer con esta fotografía antes de enviarla.');return imageTransform(text,img,'restore',!!S.restoreColorize)}
async function imageMeta(data){return await new Promise(resolve=>{const im=new Image();im.onload=()=>{const w=im.naturalWidth||1,h=im.naturalHeight||1;resolve({width:w,height:h,orientation:h>w?'vertical':w>h?'horizontal':'square',aspectRatio:w/h})};im.onerror=()=>resolve({width:0,height:0,orientation:'unknown',aspectRatio:1});im.src=data})}
async function imageTransform(text,img,action,colorize){activateWorkMode();const p=document.getElementById('prompt'),box=document.getElementById('messages');box.insertAdjacentHTML('beforeend',`<div class="msg me image-request"><img class="original-preview" src="${img.data}" alt="Imagen original"><div class="request-text">${esc(text)}</div></div>`);saveHistory('user',(action==='restore'?'[Restauración] ':'[Edición] ')+text);if(p)p.value='';S.attachments=[];renderAttachments();const wait=document.createElement('div');wait.className='msg ai working';wait.innerHTML='<span class="dots">● ● ●</span> THIAGO IA está trabajando tu imagen según la instrucción…';box.appendChild(wait);scrollWork();try{const meta=await imageMeta(img.data);const d=await api('/api/image',{method:'POST',body:JSON.stringify({prompt:text+imageSizeInstruction(text),action,image:img.data,colorize,sourceWidth:meta.width,sourceHeight:meta.height,orientation:(requestedImageSize(text)?.orientation||meta.orientation),aspectRatio:(requestedImageSize(text)?.aspectRatio||meta.aspectRatio),requestedSize:requestedImageSize(text)})});wait.classList.remove('working');wait.innerHTML=`<div>${action==='restore'?'Fotografía restaurada':'Imagen modificada'}:</div><img class="generated" src="${d.image}" alt="Resultado"><a class="download" href="${d.image}" download="thiago-ia-resultado.png">Abrir / guardar imagen</a>`;saveHistory('assistant',action==='restore'?'Fotografía restaurada':'Imagen modificada',d.image);S.attachments=[];renderAttachments();await refreshUser();scrollWork()}catch(e){wait.classList.remove('working');wait.textContent=e.message;wait.classList.add('warn');scrollWork()}}
async function refreshUser(){try{S.user=(await api('/api/me')).user;const pct=document.getElementById('usagePct');if(pct)pct.textContent=(S.user.imageUsage?.percent??100)+'%';const fill=document.querySelector('.usage-fill');if(fill)fill.style.width=(S.user.imageUsage?.percent??100)+'%'}catch{}}
function plansView(){const current=S.user?.plan;const cards=[{id:'basic',name:'BÁSICO',price:85,tag:'Para comenzar',features:['Chat con IA e investigación','Crear y mejorar imágenes','Restaurar fotografías','Traducción','Documentos Word en Arial 12'],off:['Vectorización profesional']},{id:'pro',name:'PRO',price:180,tag:'MÁS POPULAR',features:['Todo lo del plan BÁSICO','Mayor capacidad de imágenes','Mejorar y restaurar imágenes','Vectorización profesional incluida','Documentos y herramientas avanzadas'],off:[]},{id:'business',name:'NEGOCIO',price:300,tag:'MÁXIMO PODER',features:['Todo lo del plan PRO','Mayor capacidad diaria de imágenes','Vectorización con uso amplio','Herramientas para trabajo intensivo','Prioridad para funciones avanzadas'],off:[]}];return `<section class="plans-page"><div class="section-title"><span class="eyebrow">PLANES THIAGO IA</span><h1>Elige el plan ideal para ti</h1><p>Funciones claras para cada nivel de trabajo. Los cambios siempre requieren aprobación del administrador.</p></div><div class="plans premium-plans">${cards.map(p=>`<article class="plan premium-plan ${current===p.id?'current':''} ${p.id==='pro'?'featured':''}"><div class="plan-top"><span class="plan-icon">${p.id==='basic'?'✦':p.id==='pro'?'★':'♛'}</span><span class="plan-tag">${p.tag}</span></div><h2>${p.name}</h2><div class="price">Q${p.price}<small>/ 30 días</small></div><div class="feature-list">${p.features.map(f=>`<div class="feature yes">✓ ${f}</div>`).join('')}${p.off.map(f=>`<div class="feature no">× ${f}</div>`).join('')}</div><button class="primary" onclick="requestPlan('${p.id}')">${current===p.id&&planState().active?'RENOVAR PLAN':'CAMBIAR A '+p.name}</button>${current===p.id?'<div class="current-label">PLAN ACTUAL</div>':''}</article>`).join('')}</div><div class="card plan-help"><h3>¿Qué puedes hacer en THIAGO IA?</h3><div class="service-strip"><span>💬 Chat e investigación</span><span>🖼 Imágenes IA</span><span>✨ Mejorar imágenes</span><span>♻ Restaurar fotos</span><span>🌐 Traducción</span><span>◇ Vectorizar</span><span>📄 Word</span></div></div></section>`}
async function requestPlan(plan){if(S.user.plan===plan&&planState().active){if(!confirm('Este es tu plan actual. ¿Deseas solicitar una renovación anticipada?'))return;}try{await api('/api/plans/request',{method:'POST',body:JSON.stringify({plan})});S.selectedPlan=plan;S.view='pagocliente';client();alert('Solicitud enviada. Ahora realiza la transferencia y adjunta tu comprobante.')}catch(e){alert(e.message)}}
async function admin(){try{S.admin=await api('/api/admin/dashboard')}catch{return login()}const d=S.admin;let body='';if(S.view==='accesos')body=`<div class="card"><h2>🔑 Solicitudes de acceso</h2>${tableCodes(d.codes)}</div>`;else if(S.view==='planes')body=`<div class="card"><h2>Solicitudes de plan</h2>${tablePlans(d.planRequests,d.users)}</div>`;else if(S.view==='usuarios')body=`<div class="card"><h2>Usuarios</h2>${tableUsers(d.users)}</div>`;else if(S.view==='pagos')body=adminPaymentsView(d);else if(S.view==='renovaciones')body=`<div class="card"><h2>Renovaciones</h2>${tableRenew(d.users,d.planRequests)}</div>`;else if(S.view==='config')body=adminConfigView(d);else body=`<div class="hero"><h1>Panel de Administrador</h1><p class="sub">Control central de THIAGO IA</p></div><div class="grid"><div class="card"><span class="muted">USUARIOS</span><div class="stat">${d.users.length}</div></div><div class="card"><span class="muted">CÓDIGOS PENDIENTES</span><div class="stat">${d.codes.length}</div></div><div class="card"><span class="muted">SOLICITUDES DE PLAN</span><div class="stat">${d.planRequests.filter(x=>x.status==='pending').length}</div></div></div>`;A.innerHTML=`<div class="shell">${nav('admin')}<main class="main ${S.workMode&&S.view==='inicio'?'work-mode':''}"><div class="topbar"><span class="badge">ADMINISTRADOR</span><span>THIAGO IA V32.0</span></div>${body}</main></div>`}
function paymentClientView(){setTimeout(loadPaymentInfo,0);return `<section class="payment-page"><div class="section-title"><span class="eyebrow">PAGO DE PLAN</span><h1>Transferencia y comprobante</h1><p>El dinero se envía directamente a la cuenta bancaria indicada por THIAGO IA. La plataforma no guarda el dinero.</p></div><div class="grid payment-grid"><div class="card"><h2>Datos para transferencia</h2><div id="bankInfo"><p class="muted">Cargando datos bancarios…</p></div></div><div class="card"><h2>Enviar comprobante</h2><label>Plan pagado</label><select id="payPlan" class="field"><option value="basic">BÁSICO — Q85</option><option value="pro">PRO — Q180</option><option value="business">NEGOCIO — Q300</option></select><label>Número de operación / referencia (opcional)</label><input id="payRef" class="field" placeholder="Ej. 123456789"><label>Comprobante</label><input id="payReceipt" class="field" type="file" accept="image/*,application/pdf"><button class="primary" onclick="submitPayment()">ENVIAR COMPROBANTE</button><p class="muted">El administrador verificará manualmente la transferencia antes de activar el plan.</p></div></div></section>`}
async function loadPaymentInfo(){try{const d=await api('/api/payment-info');const el=document.getElementById('bankInfo');if(!el)return;el.innerHTML=d.accountNumber?`<div class="bank-box"><b>${esc(d.bankName||'Banco')}</b><p>Titular: <strong>${esc(d.accountName||'—')}</strong></p><p>Cuenta: <strong>${esc(d.accountNumber)}</strong></p><p>Tipo: <strong>${esc(d.accountType||'—')}</strong></p><p class="muted">${esc(d.instructions||'')}</p></div>`:`<div class="warn">El administrador todavía no ha configurado la cuenta bancaria.</div>`;const sel=document.getElementById('payPlan');if(sel&&S.selectedPlan)sel.value=S.selectedPlan}catch(e){}}
async function submitPayment(){const f=document.getElementById('payReceipt')?.files?.[0];if(!f)return alert('Adjunta el comprobante de transferencia.');if(f.size>9*1024*1024)return alert('El comprobante no debe superar 9 MB.');const reader=new FileReader();reader.onload=async()=>{try{await api('/api/payments',{method:'POST',body:JSON.stringify({plan:document.getElementById('payPlan').value,reference:document.getElementById('payRef').value,receipt:reader.result,receiptName:f.name})});alert('Comprobante enviado. Queda pendiente de verificación por el administrador.');S.selectedPlan=null;S.view='inicio';client()}catch(e){alert(e.message)}};reader.readAsDataURL(f)}
function adminPaymentsView(d){const pays=[...(d.payments||[])].reverse();const pending=pays.filter(x=>x.status==='pending').length,approved=pays.filter(x=>x.status==='approved').length,total=pays.filter(x=>x.status==='approved').reduce((a,x)=>a+Number(x.amount||0),0);return `<section class="admin-payments"><div class="section-title"><span class="eyebrow">ADMINISTRACIÓN</span><h1>Pagos y comprobantes</h1><p>Verificación manual de transferencias. Apruebe únicamente después de confirmar que el dinero llegó a su cuenta bancaria.</p></div><div class="grid"><div class="card"><span class="muted">PAGOS PENDIENTES</span><div class="stat">${pending}</div></div><div class="card"><span class="muted">PAGOS APROBADOS</span><div class="stat">${approved}</div></div><div class="card"><span class="muted">TOTAL APROBADO</span><div class="stat">Q${total}</div></div></div><div class="card"><table class="table"><tr><th>Cliente</th><th>Plan</th><th>Monto</th><th>Fecha</th><th>Estado</th><th>Comprobante</th><th>Acción</th></tr>${pays.map(x=>{const u=(d.users||[]).find(z=>z.id===x.userId)||{};return `<tr><td>${esc(u.name||x.email)}</td><td>${planName(x.plan)}</td><td>Q${x.amount}</td><td>${new Date(x.createdAt).toLocaleString()}</td><td><span class="pay-status ${x.status}">${x.status}</span></td><td><button class="smallbtn" onclick="viewReceipt('${x.id}')">Ver</button></td><td>${x.status==='pending'?`<button class="smallbtn approve" onclick="paymentAction('${x.id}','approve')">Aprobar</button><button class="smallbtn reject" onclick="paymentAction('${x.id}','reject')">Rechazar</button>`:'—'}</td></tr>`}).join('')||'<tr><td colspan="7">Sin pagos registrados</td></tr>'}</table></div><div id="receiptViewer"></div></section>`}
function viewReceipt(id){const x=(S.admin?.payments||[]).find(z=>z.id===id);if(!x)return;const u=(S.admin?.users||[]).find(z=>z.id===x.userId)||{};const box=document.getElementById('receiptViewer');if(!box)return;const media=String(x.receipt).startsWith('data:application/pdf')?`<iframe class="receipt-frame" src="${x.receipt}"></iframe>`:`<img class="receipt-image" src="${x.receipt}" alt="Comprobante">`;box.innerHTML=`<div class="card receipt-detail"><h2>Detalle del pago</h2><p><b>Cliente:</b> ${esc(u.name||x.email)}</p><p><b>Correo:</b> ${esc(x.email)}</p><p><b>Plan:</b> ${planName(x.plan)} · <b>Monto:</b> Q${x.amount}</p><p><b>Referencia:</b> ${esc(x.reference||'No indicada')}</p>${media}</div>`;box.scrollIntoView({behavior:'smooth'})}
async function paymentAction(id,action){if(!confirm(action==='approve'?'¿Confirma que el dinero ya llegó a su cuenta y desea activar el plan?':'¿Desea rechazar este pago?'))return;try{await api('/api/admin/payment/'+id,{method:'POST',body:JSON.stringify({action})});admin()}catch(e){alert(e.message)}}
function adminConfigView(d){const x=d.settings||{};return `<section><div class="section-title"><span class="eyebrow">CONFIGURACIÓN</span><h1>Planes y cuenta bancaria</h1></div><div class="grid"><div class="card"><h2>Precios</h2><p>BÁSICO <b>Q85</b> · PRO <b>Q180</b> · NEGOCIO <b>Q300</b></p><p class="muted">Los precios actuales se mantienen sin cambios.</p></div><div class="card"><h2>Cuenta para recibir pagos</h2><input id="bankName" class="field" placeholder="Banco" value="${esc(x.bankName||'')}"><input id="accountName" class="field" placeholder="Nombre del titular" value="${esc(x.accountName||'')}"><input id="accountNumber" class="field" placeholder="Número de cuenta" value="${esc(x.accountNumber||'')}"><input id="accountType" class="field" placeholder="Tipo de cuenta: monetaria / ahorro" value="${esc(x.accountType||'')}"><textarea id="paymentInstructions" class="field" placeholder="Instrucciones de pago">${esc(x.paymentInstructions||'')}</textarea><button class="primary" onclick="savePaymentSettings()">GUARDAR DATOS BANCARIOS</button></div></div></section>`}
async function savePaymentSettings(){try{await api('/api/admin/payment-settings',{method:'POST',body:JSON.stringify({bankName:document.getElementById('bankName').value,accountName:document.getElementById('accountName').value,accountNumber:document.getElementById('accountNumber').value,accountType:document.getElementById('accountType').value,paymentInstructions:document.getElementById('paymentInstructions').value})});alert('Datos bancarios guardados.');admin()}catch(e){alert(e.message)}}
function tableCodes(a){return `<table class="table"><tr><th>Correo</th><th>Código</th><th>Vence</th></tr>${a.map(x=>`<tr><td>${esc(x.email)}</td><td><b>${x.code}</b></td><td>${new Date(x.expiresAt).toLocaleTimeString()}</td></tr>`).join('')||'<tr><td colspan=3>Sin solicitudes</td></tr>'}</table>`}
function tableUsers(a){return `<table class="table"><tr><th>Cliente</th><th>Correo</th><th>Plan</th><th>Vence</th></tr>${a.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${planName(x.plan)}</td><td>${x.planExpires?new Date(x.planExpires).toLocaleDateString():'—'}</td></tr>`).join('')}</table>`}
function tablePlans(a,u){return `<table class="table"><tr><th>Cliente</th><th>Actual</th><th>Solicita</th><th>Estado</th><th>Acción</th></tr>${a.map(x=>{let us=u.find(z=>z.id===x.userId)||{};return `<tr><td>${esc(us.name||x.email)}</td><td>${planName(x.currentPlan)}</td><td>${planName(x.requestedPlan)}</td><td>${x.status}</td><td>${x.status==='pending'?`<button class="smallbtn" onclick="planAction('${x.id}','approve')">Aprobar</button><button class="smallbtn" onclick="planAction('${x.id}','reject')">Rechazar</button>`:'—'}</td></tr>`}).join('')||'<tr><td colspan=5>Sin solicitudes</td></tr>'}</table>`}
function tableRenew(a,r){const renew=(r||[]).filter(x=>x.kind==='renewal'&&x.status==='pending');const expired=a.filter(x=>x.plan&&(!x.planExpires||new Date(x.planExpires).getTime()<=Date.now()));return `<h3>Solicitudes pendientes</h3><table class="table"><tr><th>Cliente</th><th>Plan</th><th>Solicitud</th><th>Acción</th></tr>${renew.map(x=>{const u=a.find(z=>z.id===x.userId)||{};return `<tr><td>${esc(u.name||x.email)}</td><td>${planName(x.requestedPlan)}</td><td>RENOVACIÓN</td><td><button class="smallbtn" onclick="planAction('${x.id}','approve')">Aprobar renovación</button><button class="smallbtn" onclick="planAction('${x.id}','reject')">Rechazar</button></td></tr>`}).join('')||'<tr><td colspan=4>Sin renovaciones pendientes</td></tr>'}</table><h3>Planes vencidos</h3><table class="table"><tr><th>Cliente</th><th>Plan</th><th>Venció</th></tr>${expired.map(x=>`<tr><td>${esc(x.name)}</td><td>${planName(x.plan)}</td><td>${x.planExpires?new Date(x.planExpires).toLocaleDateString():'—'}</td></tr>`).join('')||'<tr><td colspan=3>Sin planes vencidos</td></tr>'}</table>`}
async function planAction(id,action){try{await api('/api/admin/plan-request/'+id,{method:'POST',body:JSON.stringify({action})});admin()}catch(e){alert(e.message)}}
(async()=>{if(!S.token)return login();try{const d=await api('/api/me');if(d.role==='admin'){S.role='admin';S.view='dashboard';admin()}else{S.role='client';S.user=d.user;client()}}catch{if(S.role==='admin')sessionStorage.removeItem('thiago_admin_token');else sessionStorage.removeItem('thiago_client_token');S.token=null;S.role=null;login()}})();
